html:
{#- Change of Employment Details letter, laid out as the approved Word template.
     Terms fields are read under both the staging and the BA names. -#}
{%- set terms_required = doc.get("term_changes_required") or doc.get("properties_changes_required") -%}
{%- set term_rows = (doc.get("employment_terms") or doc.get("properties") or []) if terms_required else [] -%}
{%- set day_off_required = doc.get("day_off_terms_required") -%}
{%- set benefit_rows = (doc.get("benefit") or []) if doc.get("benefits_changes_required") else [] -%}
{%- set salary_required = doc.get("salary_update_required") -%}
{%- set hr_user = frappe.db.get_single_value("HR Settings", "custom_hr_manager") -%}
{%- set hr_manager = frappe.db.get_value("Employee", {"user_id": hr_user}, ["employee_name", "designation"], as_dict=True) if hr_user else none -%}

{%- macro show_date(value) -%}{{ frappe.format(value, {"fieldtype": "Date"}) if value else "" }}{%- endmacro -%}
{%- macro show_new_value(row) -%}
{%- if row.new_value and row.new_value_doctype == "Employee" -%}
{{ row.new_value }} - {{ frappe.db.get_value("Employee", row.new_value, "employee_name") or "" }}
{%- else -%}
{{ row.new_value or "" }}
{%- endif -%}
{%- endmacro -%}
{%- macro columns() -%}<colgroup><col class="coe-c-terms"><col class="coe-c-val"><col class="coe-c-val"></colgroup>{%- endmacro -%}
{%- macro header_row() -%}
        <tr>
            <th>{{ _("Terms") }}</th>
            <th>{{ _("Current Details") }}</th>
            <th>{{ _("New Details") }}</th>
        </tr>
{%- endmacro -%}
{%- macro salary_cell(lines) -%}
{%- for l in lines %}
            <div class="coe-line{{ ' coe-total' if loop.last else '' }}">{{ l.label }}: {{ l.value }}</div>
{%- endfor %}
{%- endmacro -%}

<style>
    .coe-doc { font-family: Arial, Helvetica, sans-serif; color: #000; font-size: 10pt; line-height: 1.25; }
    .coe-doc p { margin: 0; }
    .coe-gap { margin-top: 8pt !important; }
    .coe-gap-lg { margin-top: 14pt !important; }
    .coe-sign-space { margin-top: 36pt !important; }
    .coe-letterhead { text-align: center; }
    .coe-letterhead img { max-height: 60px; width: auto !important; max-width: 100%; }
    .coe-emp p { margin-bottom: 4pt; }
    .coe-title { text-align: center; font-weight: bold; }
    .coe-heading { font-weight: bold; }
    .coe-table { width: 100%; border-collapse: collapse; table-layout: fixed; margin-top: 8pt; }
    .coe-c-terms { width: 30%; }
    .coe-c-val { width: 35%; }
    .coe-table th, .coe-table td { border: 1px solid #000; padding: 3px 5px !important; vertical-align: top; word-wrap: break-word; }
    .coe-table th { text-align: center; font-weight: bold; }
    .coe-table tr { page-break-inside: avoid; }
    .coe-total { font-weight: bold; }
    .coe-benefits { width: 100%; border-collapse: collapse; margin-top: 4pt; }
    .coe-benefits td { border: 0; padding: 1px 5px !important; vertical-align: top; }
    .coe-b-label { width: 30%; }
    .coe-b-colon { width: 2%; }
    .coe-closing { page-break-inside: avoid; }
</style>

<div class="coe-doc">

    <div class="coe-letterhead"><img src="{{ pow_logo_src() }}" alt="ONE FM"></div>

    <div class="coe-emp coe-gap">
        <p><b>{{ _("Employee ID") }}:</b> {{ doc.employee or "" }}</p>
        <p><b>{{ _("Employee Name") }}:</b> {{ doc.employee_name or "" }}</p>
        <p><b>{{ _("Designation") }}:</b> {{ doc.designation or "" }}</p>
        <p><b>{{ _("Project") }}:</b> {{ doc.project_allocation or "" }}</p>
        <p class="coe-gap"><b>{{ _("Date") }}</b>: {{ show_date(doc.creation) }}</p>
    </div>

    <p class="coe-gap coe-title">{{ _("CHANGE OF EMPLOYMENT DETAILS") }}</p>

    <p class="coe-gap"><b>{{ _("Dear {0},").format(doc.employee_name or "") }}</b></p>

    <p class="coe-gap">{{ _("We are pleased to inform you that you have below {0}, effective {1} in recognition of your performance and contribution to One Facilities Management.").format("<b>" ~ _("Changes in your Employment Terms") ~ "</b>", "<b>" ~ show_date(doc.effective_date_of_change) ~ "</b>") }}</p>

    {%- if term_rows or day_off_required %}
    <table class="coe-table">
        {{ columns() }}
        {{ header_row() }}
        {%- for row in term_rows %}
        <tr>
            <td>{{ row.get("terms") or row.get("property") or "" }}</td>
            <td>{{ row.old_value or "" }}</td>
            <td>{{ show_new_value(row) }}</td>
        </tr>
        {%- endfor %}
        {%- if day_off_required %}
        <tr>
            <td>{{ _("Day Off Category") }}</td>
            <td>{{ doc.day_off_category_current_value or "" }}</td>
            <td>{{ doc.day_off_category_new_value or "" }}</td>
        </tr>
        <tr>
            <td>{{ _("Number of Days Off") }}</td>
            <td>{{ doc.number_of_days_off_current_value or "" }}</td>
            <td>{{ doc.number_of_days_off_new_value or "" }}</td>
        </tr>
        {%- endif %}
    </table>
    {%- endif %}

    {%- if benefit_rows %}
    <p class="coe-gap coe-heading">{{ _("Benefits") }}</p>
    <table class="coe-benefits">
        {%- for row in benefit_rows %}
        <tr>
            <td class="coe-b-label">{{ row.get("terms") or row.get("property") or "" }}</td>
            <td class="coe-b-colon">:</td>
            <td>{{ row.description or "" }}</td>
        </tr>
        {%- endfor %}
    </table>
    {%- endif %}

    {%- if salary_required %}
    <p class="coe-gap coe-heading">{{ _("Salary Update") }}</p>
    <table class="coe-table">
        {{ columns() }}
        {{ header_row() }}
        <tr>
            <td>{{ _("Base Salary") }}</td>
            <td>{{ salary_cell(coe_salary_lines(doc.current_salary_structure, doc.current_base_salary)) }}</td>
            <td>{{ salary_cell(coe_salary_lines(doc.salary_new_value, doc.base_new_value)) }}</td>
        </tr>
    </table>
    {%- endif %}

    <p class="coe-gap-lg">{{ _("All other terms and conditions of your employment remain unchanged.") }}</p>

    <p class="coe-gap">{{ _("We wish you continued success in your new role.") }}</p>

    <div class="coe-closing">
        <p class="coe-gap-lg">{{ _("Sincerely,") }}</p>
        <p class="coe-sign-space">{{ hr_manager.employee_name if hr_manager and hr_manager.employee_name else "" }}</p>
        <p>{{ hr_manager.designation if hr_manager and hr_manager.designation else "" }}</p>
    </div>

    <div class="coe-closing">
        <p class="coe-gap-lg">{{ _("I acknowledge the Changes made to my Employment Terms.") }}</p>
        <p class="coe-gap-lg"><b>{{ _("Employee Signature") }}:</b></p>
        <p class="coe-gap"><b>{{ _("Date") }}:</b></p>
    </div>

</div>
